stress_pool_counterparties<-function(baseline_cashflows,exposure_contracts,netting_sets,exposure_paths,collateral_paths,settlement_terms,scenario_contract,party_mapping,party_default_paths,shared_innovations,as_of,context=NULL){
 .cr_data_date(as_of,'as_of');parsed<-.cr_st_scenarios(scenario_contract,as_of,context);contract<-parsed$contract;ctx<-parsed$context;sids<-unlist(contract$scenario_ids,use.names=FALSE);dates<-unlist(contract$dates,use.names=FALSE);horizon<-tail(dates,1);keyfn<-function(...).cr_hash(list(...));baseline<-list();ids<-character()
 for(row in .cr_data_rows(baseline_cashflows,'baseline_cashflows')){.cr_data_required(row,c('scenario_id','cashflow_id','date','amount'));key<-keyfn(row$scenario_id,.cr_sc_text(row$cashflow_id,'cashflow_id'));if(!is.null(baseline[[key]])||!(row$scenario_id%in%sids)||!(.cr_data_date(as_of,'as_of')<=.cr_data_date(row$date,'date')&&.cr_data_date(row$date,'date')<=.cr_data_date(horizon,'horizon'))) .cr_error('STRUCTURED_CASHFLOW','Unique aligned baseline cashflows within horizon required');.cr_sc_number(row$amount,'amount',0);baseline[[key]]<-row;ids<-union(ids,row$cashflow_id)};expected<-character();for(s in sids)for(i in ids)expected<-c(expected,keyfn(s,i));if(!setequal(names(baseline),expected)) .cr_error('STRUCTURED_CASHFLOW','Each baseline monetary ID needs every scenario');exposures<-sets<-list();linked<-parties<-character()
 for(row in .cr_data_rows(exposure_contracts,'exposure_contracts')){.cr_data_required(row,c('exposure_id','counterparty_id','netting_set_id','role','basis','cashflow_ids'));eid<-.cr_sc_text(row$exposure_id,'exposure_id');for(k in c('counterparty_id','netting_set_id')) .cr_sc_text(row[[k]],k);supported<-list(SERVICER='CASH_HELD',ACCOUNT_BANK='CASH_HELD',GUARANTOR='GUARANTEE_RECEIVABLE',SWAP='REPLACEMENT');if(!is.null(exposures[[eid]])||!(row$role%in%names(supported))||row$basis!=supported[[row$role]]) .cr_error('STRUCTURED_COUNTERPARTY','Unique exposures and explicit supported role/basis required');cashids<-unlist(row$cashflow_ids,use.names=FALSE);if(anyDuplicated(cashids)||any(!(cashids%in%ids)|cashids%in%linked)||(row$basis=='REPLACEMENT'&&length(cashids)>0)||(row$basis!='REPLACEMENT'&&!length(cashids))) .cr_error('STRUCTURED_DOUBLE_COUNT','Distinct existing monetary IDs required; replacement marks cannot duplicate baseline cash');linked<-union(linked,cashids);exposures[[eid]]<-row;parties<-union(parties,row$counterparty_id)};if(!length(exposures)) .cr_error('STRUCTURED_COUNTERPARTY','Nonempty exposure contracts required');collateral_ids<-character()
 for(row in .cr_data_rows(netting_sets,'netting_sets')){.cr_data_required(row,c('netting_set_id','counterparty_id','enforceable','collateral_contract_id','collateral_convention','default_timing'));nid<-.cr_sc_text(row$netting_set_id,'netting_set_id');cid<-.cr_sc_text(row$collateral_contract_id,'collateral_contract_id');if(!is.null(sets[[nid]])||cid%in%collateral_ids||!(row$counterparty_id%in%parties)||!is.logical(row$enforceable)||length(row$enforceable)!=1L||is.na(row$enforceable)||row$collateral_convention!='RECEIVED_TRANSFERABLE'||row$default_timing!='AFTER_COLLATERAL_SNAPSHOT_BEFORE_CASHFLOWS') .cr_error('STRUCTURED_NETTING','Unique set/collateral IDs and explicit legal/default timing conventions required');members<-Filter(function(e)e$netting_set_id==nid,exposures);if(!length(members)||any(vapply(members,function(e)e$counterparty_id!=row$counterparty_id,TRUE))||(!row$enforceable&&length(members)!=1L)) .cr_error('STRUCTURED_NETTING','Unenforceable netting requires singleton sets; legal counterparty must agree');sets[[nid]]<-row;collateral_ids<-union(collateral_ids,cid)};if(!setequal(vapply(exposures,function(e)e$netting_set_id,''),names(sets))) .cr_error('STRUCTURED_NETTING','Every exposure needs exactly one defined netting set');ev<-.cr_st_party_events(contract,party_mapping,parties,party_default_paths,shared_innovations);pmap<-ev$party_map;defaults<-ev$defaults;events<-ev$events;marks<-collateral<-terms<-list()
 for(row in .cr_data_rows(exposure_paths,'exposure_paths')){.cr_data_required(row,c('scenario_id','exposure_id','date','signed_replacement_mark'));key<-keyfn(row$scenario_id,row$exposure_id,row$date);if(!is.null(marks[[key]])||!(row$scenario_id%in%sids)||!(row$exposure_id%in%names(exposures))||!(row$date%in%dates)) .cr_error('STRUCTURED_EXPOSURE','Complete unique aligned signed replacement snapshots required');mark<-.cr_sc_number(row$signed_replacement_mark,'signed_replacement_mark');if(exposures[[row$exposure_id]]$basis!='REPLACEMENT'&&mark!=0) .cr_error('STRUCTURED_DOUBLE_COUNT','Cash-linked exposure derives its claim from baseline; no added replacement mark');marks[[key]]<-mark};expected<-character();for(s in sids)for(e in names(exposures))for(d in dates)expected<-c(expected,keyfn(s,e,d));if(!setequal(names(marks),expected)) .cr_error('STRUCTURED_EXPOSURE','Full exposure/scenario/risk-date grid required')
 for(row in .cr_data_rows(collateral_paths,'collateral_paths')){.cr_data_required(row,c('scenario_id','netting_set_id','date','known_at','collateral_value','haircut'));key<-keyfn(row$scenario_id,row$netting_set_id,row$date);if(!is.null(collateral[[key]])||!(row$scenario_id%in%sids)||!(row$netting_set_id%in%names(sets))||!(row$date%in%dates)||.cr_data_date(row$known_at,'known_at')>.cr_data_date(row$date,'date')) .cr_error('STRUCTURED_COLLATERAL','Known-at or before default snapshot and unique aligned collateral grid required');.cr_sc_number(row$collateral_value,'collateral_value',0);.cr_sc_number(row$haircut,'haircut',0,1);collateral[[key]]<-row};expected<-character();for(s in sids)for(n in names(sets))for(d in dates)expected<-c(expected,keyfn(s,n,d));if(!setequal(names(collateral),expected)) .cr_error('STRUCTURED_COLLATERAL','Full set/scenario/risk-date collateral grid required')
 for(row in .cr_data_rows(settlement_terms,'settlement_terms')){.cr_data_required(row,c('scenario_id','counterparty_id','estate_recovery_fraction','estate_capacity','estate_delay_days','collateral_delay_days','replacement_cost','replacement_delay_days'));key<-keyfn(row$scenario_id,row$counterparty_id);if(!is.null(terms[[key]])||!(row$scenario_id%in%sids)||!(row$counterparty_id%in%parties)) .cr_error('STRUCTURED_COUNTERPARTY','Unique aligned counterparty settlement terms required');.cr_sc_number(row$estate_recovery_fraction,'estate_recovery_fraction',0,1);for(k in c('estate_capacity','replacement_cost')) .cr_sc_number(row[[k]],k,0);for(k in c('estate_delay_days','collateral_delay_days','replacement_delay_days')){n<-.cr_sc_number(row[[k]],k,0);if(n!=floor(n)) .cr_error('STRUCTURED_CALENDAR','Integer nonnegative settlement delays required')};terms[[key]]<-row};expected<-character();for(s in sids)for(p in parties)expected<-c(expected,keyfn(s,p));if(!setequal(names(terms),expected)) .cr_error('STRUCTURED_COUNTERPARTY','Full counterparty/scenario settlement terms required');adjusted<-removed<-netting<-counterparty<-ending<-list()
 flow<-function(sid,date,source,party,nid,amount,cashflow_id=NULL){if(amount!=0)adjusted[[length(adjusted)+1L]]<<-list(scenario_id=sid,date=date,source=source,counterparty_id=party,netting_set_id=nid,cashflow_id=cashflow_id,amount=.cr_sc_sum(amount))}
 for(sid in sids){removed_ids<-character();total_loss<-total_cost<-0
 for(party in sort(parties)){default<-defaults[[keyfn(sid,pmap[[party]])]];if(is.null(default)){counterparty[[length(counterparty)+1L]]<-list(scenario_id=sid,counterparty_id=party,default_date=NULL,credit_loss=0,replacement_cost=0,estate_recovery=0,collateral_recovery=0);next};term<-terms[[keyfn(sid,party)]];settlement_dates<-list();for(key in c('estate_delay_days','collateral_delay_days','replacement_delay_days')){date<-format(.cr_data_date(default,'default_date')+term[[key]],'%Y-%m-%d');if(is.na(date)||nchar(date)!=10L) .cr_error('STRUCTURED_CALENDAR','Settlement date outside supported calendar');if(date>horizon) .cr_error('STRUCTURED_UNRESOLVED','Settlement tail outside explicit horizon; extend scenarios rather than drop recovery');settlement_dates[[key]]<-date};parts<-list()
 for(nid in sort(names(sets))){if(sets[[nid]]$counterparty_id!=party)next;members<-Filter(function(e)e$netting_set_id==nid,exposures);cash_claims<-swap_marks<-numeric();positive_by_role<-setNames(rep(list(numeric()),4),c('SERVICER','ACCOUNT_BANK','GUARANTOR','SWAP'));for(e in members){mark<-marks[[keyfn(sid,e$exposure_id,default)]];swap_marks<-c(swap_marks,mark);contributions<-mark;for(cashid in e$cashflow_ids){row<-baseline[[keyfn(sid,cashid)]];if(row$date>=default){cash_claims<-c(cash_claims,row$amount);contributions<-c(contributions,row$amount);removed_ids<-union(removed_ids,cashid);removed[[length(removed)+1L]]<-list(scenario_id=sid,cashflow_id=cashid,exposure_id=e$exposure_id,counterparty_id=party,netting_set_id=nid,default_date=default,original_date=row$date,amount=row$amount)}};positive_by_role[[e$role]]<-c(positive_by_role[[e$role]],max(0,.cr_sc_sum(contributions)))};held<-.cr_sc_sum(cash_claims);replacement<-.cr_sc_sum(swap_marks);net<-.cr_sc_sum(c(held,replacement));positive<-max(0,net);snap<-collateral[[keyfn(sid,nid,default)]];coll<-min(positive,snap$collateral_value*(1-snap$haircut));unsecured<-max(0,positive-coll);parts[[length(parts)+1L]]<-list(positive_claims_by_role=lapply(positive_by_role,.cr_sc_sum),netting_set_id=nid,linked_cash_claim=held,signed_replacement_mark=replacement,net_closeout=net,positive_exposure=positive,collateral_recovery=coll,unsecured_claim=unsecured)}
 unsecured_total<-.cr_sc_sum(vapply(parts,function(p)p$unsecured_claim,0.));estate_total<-min(unsecured_total*term$estate_recovery_fraction,term$estate_capacity);credit<-colls<-numeric()
 for(p in parts){nid<-p$netting_set_id;estate<-if(unsecured_total>0)estate_total*(p$unsecured_claim/unsecured_total)else 0;loss<-max(0,p$unsecured_claim-estate);credit<-c(credit,loss);colls<-c(colls,p$collateral_recovery);flow(sid,default,'SIGNED_REPLACEMENT_OUTLAY',party,nid,-p$signed_replacement_mark);flow(sid,default,'NEGATIVE_NET_CLOSEOUT',party,nid,min(0,p$net_closeout));flow(sid,settlement_dates$collateral_delay_days,'COLLATERAL_REALIZATION',party,nid,p$collateral_recovery);flow(sid,settlement_dates$estate_delay_days,'ESTATE_RECOVERY',party,nid,estate);gross_positive<-.cr_sc_sum(unlist(p$positive_claims_by_role,use.names=FALSE));attribution<-lapply(p$positive_claims_by_role,function(amount)if(gross_positive>0)loss*(amount/gross_positive)else 0);netting[[length(netting)+1L]]<-c(list(scenario_id=sid,counterparty_id=party,default_date=default),p,list(estate_recovery=estate,credit_loss=loss,proportional_loss_by_role=attribution))}
 flow(sid,settlement_dates$replacement_delay_days,'ADDITIONAL_REPLACEMENT_COST',party,NULL,-term$replacement_cost);loss<-.cr_sc_sum(credit);total_loss<-.cr_sc_sum(c(total_loss,loss));total_cost<-.cr_sc_sum(c(total_cost,term$replacement_cost));counterparty[[length(counterparty)+1L]]<-list(scenario_id=sid,counterparty_id=party,default_date=default,credit_loss=loss,replacement_cost=term$replacement_cost,estate_recovery=estate_total,collateral_recovery=.cr_sc_sum(colls))
 }
 for(row in baseline)if(row$scenario_id==sid&&!(row$cashflow_id%in%removed_ids))flow(sid,row$date,'BASELINE_RETAINED',NULL,NULL,row$amount,row$cashflow_id);original<-.cr_sc_sum(vapply(Filter(function(r)r$scenario_id==sid,baseline),function(r)r$amount,0.));actual<-.cr_sc_sum(vapply(Filter(function(r)r$scenario_id==sid,adjusted),function(r)r$amount,0.));residual<-.cr_sc_sum(c(original,-actual,-total_loss,-total_cost));if(abs(residual)>1e-10*max(1,original,total_loss,total_cost)) .cr_error('STRUCTURED_CONSERVATION','Baseline/adjusted/credit/replacement cash reconciliation failed');ending[[length(ending)+1L]]<-list(scenario_id=sid,baseline_cash=original,adjusted_net_cash=actual,credit_loss=total_loss,additional_replacement_cost=total_cost,conservation_residual=residual)
 }
 if(length(adjusted))adjusted<-adjusted[order(vapply(adjusted,function(r)r$scenario_id,''),vapply(adjusted,function(r)r$date,''),vapply(adjusted,function(r)r$source,''),vapply(adjusted,function(r)if(is.null(r$counterparty_id))''else r$counterparty_id,''),vapply(adjusted,function(r)if(is.null(r$netting_set_id))''else r$netting_set_id,''),vapply(adjusted,function(r)if(is.null(r$cashflow_id))''else r$cashflow_id,''))]
 value<-.cr_sc_bound(list(schema_version='1.0',kind='PoolCounterpartyStress',origin=as_of,exposure_contracts=exposure_contracts,netting_sets=netting_sets,scenario_contract=contract,innovation_hash=.cr_hash(shared_innovations),input_hash=.cr_hash(list(baseline_cashflows=baseline_cashflows,exposure_contracts=exposure_contracts,netting_sets=netting_sets,exposure_paths=exposure_paths,collateral_paths=collateral_paths,settlement_terms=settlement_terms,party_mapping=party_mapping,party_default_paths=party_default_paths)),group_events=events,removed_baseline_cashflows=removed,adjusted_cashflows=adjusted,netting_results=netting,counterparty_results=counterparty,ending_states=ending))
 .cr_result(value,'structured_credit.stress_pool_counterparties','counterparty_cash_impacts',ctx,diagnostics=.cr_empty_object(),limitations='Linked baseline cash denotes existing incoming monetary claims held from origin until remittance; unearned future income must not be labeled held cash. Shared default occurs after the declared known collateral snapshot and before same-day cash. Enforceable netting is caller-declared; otherwise each set is a singleton. Received transferable collateral is allocated uniquely; posted collateral claims require the separate counterparty exposure engine. Supplied signed replacement marks create one replacement outlay or inflow and one net closeout claim/payment; derivative prices are not estimated here. Estate capacity is capped once per counterparty across sets and allocated pro rata; additional replacement cost is charged once per counterparty. All recovery dates must fit the horizon. Netting-set loss attribution to roles is proportional to positive gross claims after netting/collateral; it is an allocation convention, not a separate loss calculation. Baseline cash removed and closeout/replacement cash reconcile exactly to credit loss plus additional costs, with no repeated monetary IDs.')
}
